  VALUES ('tower-of-london', 1, 'builtin', 1, 'unmissable', 'Tower of London', 'Tower of London', 'Nine hundred years of Norman keep, prison and treasury — and it earns the crowds.', 'Neunhundert Jahre normannischer Bergfried, Gefängnis und Schatzkammer – die Menschenmengen sind verdient. Die Führungen der Yeoman Warder sind im Ticket enthalten und die besten der Stadt.', '["history","architecture","royal"]', 'Tower Hill', 'Tower Hill', 'paid', '£37', '37 £', '["fri","sat","sun","mon","tue","wed"]', 1, '["Some rooms have reduced access due to conservation works"]', 'https://www.hrp.org.uk/tower-of-london/', 'Tower of London', 51.5081, -0.0761, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('british-museum', 1, 'builtin', 2, 'unmissable', 'The British Museum', 'The British Museum', 'Free, vast, and genuinely unmissable — the Rosetta Stone, the Parthenon sculptures, the Sutton Hoo helmet, all under Foster''s Great Court roof. Pick three galleries rather than trying to see it.', 'Kostenlos, riesig und wirklich unverzichtbar – der Stein von Rosetta, die Parthenon-Skulpturen, der Helm von Sutton Hoo, alles unter Fosters Glasdach. Suchen Sie sich drei Säle aus, statt alles sehen zu wollen.', '["history","free","icon"]', 'Bloomsbury', 'Tottenham Court Road / Russell Square', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.britishmuseum.org/visit', 'British Museum', 51.5194, -0.1269, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('the-painted-hall-old-royal-naval-college', 1, 'builtin', 3, 'unmissable', 'The Painted Hall, Old Royal Naval College', 'Painted Hall, Old Royal Naval College', 'Thornhill spent nineteen years on this ceiling and it shows.', 'Thornhill hat neunzehn Jahre an dieser Decke gemalt, und man sieht es. Ein barocker Rausch über einem Speisesaal für Marineveteranen. Kostenlose Kurzführungen alle 30 Minuten.', '["architecture","art","history"]', 'Greenwich', 'Cutty Sark DLR', 'paid', '£19', '19 £', '["fri","sat","sun","mon","tue","wed"]', 1, '["Multiple partial closures during September — check the ORNC calendar before fixing a date","Lift out of order"]', 'https://ornc.org/', 'Old Royal Naval College', 51.4836, -0.0058, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('sir-john-soane-s-museum', 1, 'builtin', 4, 'unmissable', 'Sir John Soane''s Museum', 'Sir John Soane''s Museum', 'The most extraordinary interior in London, and it costs nothing.', 'Der außergewöhnlichste Innenraum Londons – und er kostet nichts. Ein Architektenhaus, seit 1837 unverändert: Spiegel, farbige Oberlichter, der Sarkophag Sethos'' I. im Keller.', '["architecture","art","free","hidden-gem"]', 'Holborn', 'Holborn', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","wed"]', 0, '[]', 'https://www.soane.org/your-visit', 'Sir John Soane''s Museum', 51.517, -0.1174, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('westminster-abbey-diamond-jubilee-galleries', 1, 'builtin', 5, 'unmissable', 'Westminster Abbey + Diamond Jubilee Galleries', 'Westminster Abbey + Diamond Jubilee Galleries', 'The coronation church — and a triforium gallery almost nobody adds on.', 'Die Krönungskirche. Für 5 £ Aufpreis bringen die Galerien Sie ins mittelalterliche Triforium, zwanzig Meter hoch, mit Blick das Kirchenschiff hinunter. Sonntags für Besucher geschlossen.', '["history","architecture","royal"]', 'Westminster', 'Westminster / St James''s Park', 'paid', '£31 + £5 galleries', '31 £ + 5 £ Galerien', '["fri","sat","mon","tue","wed"]', 1, '["Summer discount ended 1 September — full prices apply"]', 'https://www.westminster-abbey.org/', 'Westminster Abbey', 51.4994, -0.1275, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('st-paul-s-cathedral-the-dome-climb', 1, 'builtin', 6, 'unmissable', 'St Paul''s Cathedral — the dome climb', 'St Paul''s Cathedral – der Aufstieg zur Kuppel', '528 steps to the best earned view in the city.', '528 Stufen, kein Aufzug, und die Golden Gallery oben ist der schönste erarbeitete Ausblick der Stadt. Sonntags sind nur die Galerien geöffnet – deutlich günstiger.', '["architecture","views","history"]', 'City of London', 'St Paul''s', 'paid', '£27 full · Dome Sundays much less', '27 £ · sonntags nur Kuppel, deutlich günstiger', '["fri","sat","sun","mon","tue","wed"]', 1, '["FREE ''St Paul''s at Night'' Tue 15 Sept, 18:30–21:00"]', 'https://www.stpauls.co.uk/', 'St Paul''s Cathedral', 51.5138, -0.0983, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('national-gallery', 1, 'builtin', 7, 'unmissable', 'The National Gallery', 'The National Gallery', 'Van Gogh''s Sunflowers, Turner''s Fighting Temeraire, Van Eyck''s Arnolfini Portrait — free, on Trafalgar Square, and small enough to do properly in two hours.', 'Van Goghs Sonnenblumen, Turners „Fighting Temeraire“, van Eycks Arnolfini-Hochzeit – kostenlos, am Trafalgar Square und klein genug, um es in zwei Stunden richtig zu sehen.', '["art","free","icon"]', 'Trafalgar Square', 'Charing Cross', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.nationalgallery.org.uk/visiting', 'National Gallery', 51.5089, -0.1283, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('horizon-22', 1, 'builtin', 8, 'unmissable', 'Horizon 22', 'Horizon 22', 'Europe''s highest free viewing platform — and it beats the Shard.', 'Europas höchste kostenlose Aussichtsplattform, 58. Stock, mit dem Lift in 41 Sekunden. Besser als der Shard, weil man von hier aus den Shard auch sieht.', '["views","free","architecture"]', 'City of London', 'Liverpool Street / Bank', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 1, '[]', 'https://horizon22.co.uk/', '22 Bishopsgate', 51.5145, -0.0829, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('leadenhall-market-the-lloyd-s-building', 1, 'builtin', 9, 'unmissable', 'Leadenhall Market & the Lloyd''s building', 'Leadenhall Market & das Lloyd''s Building', 'Victorian iron and glass, and the Diagon Alley exterior — with Lloyd''s next door.', 'Viktorianisches Schmiedeeisen und Glas in Bordeaux, Creme und Grün – und die Kulisse der Winkelgasse. Nebenan steht Richard Rogers'' nach außen gestülptes Lloyd''s Building.', '["architecture","free","film","harry-potter"]', 'City of London', 'Monument / Bank', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '["Lloyd''s interior is closed to the public; its Open House day is Sat 19 Sept, after the trip"]', 'https://leadenhallmarket.co.uk/visit/', 'Leadenhall Market', 51.5128, -0.0835, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('victoria-and-albert-museum', 1, 'builtin', 10, 'unmissable', 'Victoria and Albert Museum', 'Victoria and Albert Museum', 'The most beautiful museum building in Britain.', 'Das schönste Museumsgebäude Großbritanniens, und das, in dem man planlos umherlaufen sollte. Freitags bis 22 Uhr geöffnet.', '["art","architecture","free","design"]', 'South Kensington', 'South Kensington', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '["Friday Late until 22:00 — 11 Sept is a Friday"]', 'https://www.vam.ac.uk/visit', 'Victoria and Albert Museum', 51.4967, -0.1719, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('warner-bros-studio-tour-the-making-of-harry-potter', 1, 'builtin', 11, 'unmissable', 'Warner Bros. Studio Tour — The Making of Harry Potter', 'Warner Bros. Studio Tour – The Making of Harry Potter', 'Not a theme park: the actual sets, props and costumes, kept.', 'Kein Freizeitpark: die echten Kulissen, Requisiten und Kostüme. Große Halle, Winkelgasse, das Hogwarts-Modell. Planen Sie den ganzen Tag ein.', '["harry-potter","film","family"]', 'Leavesden, Hertfordshire', 'Watford Junction + free shuttle', 'paid', '~£56–58.50', 'ca. 56–58,50 £', '["fri","sat","sun","mon","tue","wed"]', 1, '["Dark Arts runs 16 Sept – 8 Nov and is included in the standard ticket — book Wed 16 Sept for opening day"]', 'https://www.wbstudiotour.co.uk/', 'Warner Bros. Studio Tour London – The Making of Harry Potter', 51.6933, -0.4197, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('borough-market-the-south-bank-walk', 1, 'builtin', 12, 'unmissable', 'Borough Market & the South Bank walk', 'Borough Market & der South-Bank-Spaziergang', 'Three free hours along the river, ending in a cheese toastie.', 'Drei kostenlose Stunden am Fluss entlang, mit einem Käsetoast am Ende. Am schönsten in der Dämmerung. Montags ist der Markt geschlossen.', '["food","walk","free"]', 'Southwark', 'Westminster → London Bridge', 'free', 'Free to walk', 'Kostenlos begehbar', '["fri","sat","sun","tue","wed"]', 0, '["Kappacasein (the toastie) trades Thu–Sat only — so Fri 11 or Sat 12"]', 'https://boroughmarket.org.uk/visit-us/', 'Borough Market', 51.5056, -0.0908, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('big-ben-westminster-bridge', 1, 'builtin', 13, 'unmissable', 'Big Ben & Westminster Bridge', 'Big Ben & Westminster Bridge', 'The view everyone comes for, and it still works. Best from the south end of Westminster Bridge or the steps by County Hall — and at dusk, when the tower lights come on.', 'Der Blick, wegen dem alle kommen – und er funktioniert immer noch. Am besten vom Südende der Westminster Bridge oder von den Stufen beim County Hall, und in der Dämmerung, wenn der Turm beleuchtet wird.', '["icon","free","architecture"]', 'Westminster', 'Westminster', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.parliament.uk/visiting/', 'Big Ben', 51.5007, -0.1245, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('tate-modern', 1, 'builtin', 14, 'popular', 'Tate Modern', 'Tate Modern', 'A power station turned into the best modern art museum in Europe. Free collection, the vast Turbine Hall, and a top-floor viewing level with a free City panorama.', 'Ein Kraftwerk, umgebaut zum besten Museum für moderne Kunst in Europa. Sammlung kostenlos, dazu die gewaltige Turbinenhalle und eine Aussichtsebene mit kostenlosem Blick über die City.', '["art","free","architecture"]', 'Bankside', 'Southwark / Blackfriars', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.tate.org.uk/visit/tate-modern', 'Tate Modern', 51.5078, -0.0994, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('eltham-palace', 1, 'builtin', 15, 'exceptional', 'Eltham Palace', 'Eltham Palace', 'A 1930s Art Deco house grafted onto Edward IV''s medieval great hall.', 'Eine Art-déco-Villa der 1930er, aufgesetzt auf die mittelalterliche Halle Eduards IV. Das Bad aus Onyx, schwarzem Marmor und Goldmosaik ist der Höhepunkt.', '["architecture","history","art-deco"]', 'Eltham, SE9', 'Eltham / Mottingham rail', 'free-limited', 'FREE Mon 14 Sept only', 'Nur Mo 14. Sept. kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '["FREE all day Monday 14 September for Heritage Open Days","Lift currently out of order"]', 'https://www.english-heritage.org.uk/visit/places/eltham-palace-and-gardens/', 'Eltham Palace', 51.4472, 0.0481, 'setup', 'setup', 0);
