  VALUES ('two-temple-place', 1, 'builtin', 16, 'exceptional', 'Two Temple Place', 'Two Temple Place', 'Astor''s neo-Tudor fantasy, open a handful of days a year.', 'Astors neugotische Fantasie am Embankment – Hammerbalkendecke, Ebenholzsäulen, Buntglas. Nur an einer Handvoll Tage im Jahr geöffnet.', '["architecture","hidden-gem","free"]', 'Embankment', 'Temple', 'free-limited', 'Free on Sun 13 Sept', 'Nur So 13. Sept. kostenlos', '["sun"]', 0, '["Single-day opportunity — the highest-priority Open House target of the trip"]', 'https://twotempleplace.org/whats-on/', 'Two Temple Place', 51.5116, -0.1124, 'setup', 'setup', 0);
