  VALUES ('hampstead-the-heath-and-kenwood-house', 1, 'builtin', 17, 'exceptional', 'Hampstead, the Heath and Kenwood House', 'Hampstead, die Heath und Kenwood House', 'The best day in London for people who want to walk.', 'Der beste Tag Londons für Leute, die gerne laufen. Über die Heath zum Parliament Hill, dann Kenwood: kostenlos, mit einem Vermeer und einem späten Rembrandt.', '["walk","art","free","nature"]', 'Hampstead / Highgate', 'Hampstead', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.english-heritage.org.uk/visit/places/kenwood/', 'Kenwood House', 51.5714, -0.1675, 'setup', 'setup', 0);
