  VALUES ('kew-gardens-the-palm-house', 1, 'builtin', 18, 'exceptional', 'Kew Gardens — the Palm House', 'Kew Gardens – das Palmenhaus', 'Your last look at the 1848 Palm House for five years.', 'Der letzte Blick auf das Palmenhaus von 1848 für fünf Jahre: 2027 beginnt die Sanierung. Das Temperate House ist das größte viktorianische Gewächshaus der Welt.', '["nature","architecture","last-chance"]', 'Kew, Richmond', 'Kew Gardens', 'paid', 'Ticketed — cheaper online', 'Eintritt – online günstiger', '["fri","sat","sun","mon","tue","wed"]', 1, '["Waterlily House closed for all of 2026","Palm House closes in 2027 for a five-year restoration"]', 'https://www.kew.org/kew-gardens/palm-house-renovation', 'Palm House, Kew Gardens', 51.4792, -0.2928, 'setup', 'setup', 0);
