  VALUES ('sky-garden', 1, 'builtin', 19, 'exceptional', 'Sky Garden', 'Sky Garden', 'Three storeys of planting under a glass dome on top of the Walkie-Talkie.', 'Drei Stockwerke Bepflanzung unter einer Glaskuppel auf dem Walkie-Talkie, mit Freiluftterrasse zum Shard. Niedriger und voller als Horizon 22, aber der Raum selbst ist die Attraktion.', '["views","free","architecture"]', 'City of London', 'Monument', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 1, '[]', 'https://skygarden.london/', '20 Fenchurch Street', 51.5113, -0.0835, 'setup', 'setup', 0);
