  VALUES ('natural-history-museum-hintze-hall', 1, 'builtin', 20, 'exceptional', 'Natural History Museum — Hintze Hall', 'Natural History Museum – Hintze Hall', 'A terracotta cathedral to nature with a blue whale hanging down the middle.', 'Kommen Sie wegen des Raums, nicht wegen der Dinosaurier. Eine Terrakotta-Kathedrale der Natur von 1881, mit einem Blauwalskelett in der Mitte.', '["architecture","free","family"]', 'South Kensington', 'South Kensington', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.nhm.ac.uk/visit.html', 'Natural History Museum, London', 51.4961, -0.1764, 'setup', 'setup', 0);
