  VALUES ('highgate-cemetery', 1, 'builtin', 21, 'exceptional', 'Highgate Cemetery', 'Highgate Cemetery', 'Victorian death at full theatrical volume.', 'Viktorianischer Totenkult in voller Lautstärke: die Egyptian Avenue, der Circle of Lebanon um eine 300 Jahre alte Zeder. Der Westteil nur mit Führung.', '["history","hidden-gem","walk"]', 'Highgate', 'Archway (10 min uphill)', 'paid', 'Ticketed', 'Eintritt', '["fri","sat","sun","mon","tue","wed"]', 1, '["Steep gravel paths in the West Cemetery"]', 'https://highgatecemetery.org/', 'Highgate Cemetery', 51.567, -0.147, 'setup', 'setup', 0);
