  VALUES ('the-wallace-collection', 1, 'builtin', 22, 'exceptional', 'The Wallace Collection', 'The Wallace Collection', 'Fragonard''s The Swing and the Laughing Cavalier, in silk-hung rooms with nobody in them.', 'Fragonards „Die Schaukel“ und der „Lachende Kavalier“ in seidenbespannten Räumen, in denen fast niemand ist. Dazu die beste Rüstkammer außerhalb der Royal Armouries.', '["art","free","hidden-gem"]', 'Marylebone', 'Bond Street', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '["Parts of the museum may close at short notice"]', 'https://www.wallacecollection.org/visit/', 'Wallace Collection', 51.5175, -0.153, 'setup', 'setup', 0);
