  VALUES ('guildhall-roman-amphitheatre', 1, 'builtin', 24, 'exceptional', 'Guildhall Roman Amphitheatre', 'Römisches Amphitheater der Guildhall', 'London''s Roman amphitheatre, in a basement under the Guildhall.', 'Londons römisches Amphitheater im Keller der Guildhall, stimmungsvoll beleuchtet, mit projizierten Zuschauern. Oben im Hof zeichnet eine schwarze Linie seinen Umriss nach.', '["history","roman","free"]', 'City of London', 'Bank / St Paul''s / Moorgate', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","tue","wed"]', 0, '["The new London Museum at Smithfield does not open until 28 Nov 2026"]', 'https://www.cityoflondon.gov.uk/things-to-do/attractions-museums-entertainment/guildhall-art-gallery/visit-guildhall-art-gallery', 'London Roman Amphitheatre', 51.5159, -0.092, 'setup', 'setup', 0);
