  VALUES ('columbia-road-flower-market', 1, 'builtin', 25, 'exceptional', 'Columbia Road Flower Market', 'Columbia Road Flower Market', 'The most Sunday-specific thing in London.', 'Das sonntäglichste Erlebnis Londons: eine schmale viktorianische Straße voller Blumen und schreiender Händler. Vor 9 Uhr kommt man durch, nach 14 Uhr fallen die Preise.', '["market","free","sunday-only"]', 'Bethnal Green / Hoxton', 'Hoxton (Overground)', 'free', 'Free', 'Kostenlos', '["sun"]', 0, '["Fifteen minutes'' walk from Brick Lane — do them together"]', 'https://columbiaroad.info/', 'Columbia Road', 51.5294, -0.0694, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('tower-bridge-and-the-engine-rooms', 1, 'builtin', 26, 'exceptional', 'Tower Bridge and the Engine Rooms', 'Tower Bridge und die Maschinenräume', 'A glass floor you stand on while a bus drives underneath.', 'Ein Glasboden, auf dem man steht, während unten ein Bus durchfährt. Übersehen wird meist der beste Teil: die viktorianischen Dampfmaschinen, die die Brücke hoben.', '["architecture","history","views"]', 'Tower Hill / Bermondsey', 'Tower Hill / London Bridge', 'paid', '£18', '18 £', '["fri","sat","sun","mon","tue","wed"]', 1, '[]', 'https://www.towerbridge.org.uk/', 'Tower Bridge', 51.5056, -0.0753, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('hampton-court-palace', 1, 'builtin', 27, 'exceptional', 'Hampton Court Palace', 'Hampton Court Palace', 'Two palaces in one — Henry VIII''s Tudor kitchens running into Wren''s baroque state apartments.', 'Zwei Paläste in einem – Heinrichs VIII. Tudor-Küchen gehen in Wrens barocke Staatsgemächer über. Dazu das Heckenlabyrinth und 24 Hektar Gärten.', '["history","royal","architecture","gardens"]', 'East Molesey, Surrey', 'Hampton Court rail (35 min from Waterloo)', 'paid', '£29 off-peak / £32 peak', '29 £ / 32 £ (Wochenende)', '["fri","sat","sun","mon","tue","wed"]', 1, '["Gardens FREE Sat 12 and Sun 13 Sept, 10:00–16:00","Bridgerton filming locations included in general admission"]', 'https://www.hrp.org.uk/hampton-court-palace/', 'Hampton Court Palace', 51.4033, -0.3375, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('imperial-war-museum-london', 1, 'builtin', 28, 'exceptional', 'Imperial War Museum London', 'Imperial War Museum London', 'Free, daily, and the Holocaust Galleries are among the most carefully made museum spaces anywhere.', 'Kostenlos, täglich geöffnet, und die Holocaust-Galerien gehören zu den sorgfältigsten Museumsräumen überhaupt. Nehmen Sie sich Zeit dafür.', '["history","free","wartime"]', 'Lambeth', 'Lambeth North / Elephant & Castle', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '["Free exhibition ''Childhood in War'' runs 31 July 2026 – 28 Feb 2027"]', 'https://www.iwm.org.uk/visits/iwm-london', 'Imperial War Museum', 51.4958, -0.1086, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('barbican-conservatory', 1, 'builtin', 29, 'exceptional', 'Barbican Conservatory', 'Barbican Conservatory', 'Two thousand tropical species growing through raw Brutalist concrete.', 'Zweitausend tropische Arten, die durch rohen Beton wachsen – Londons zweitgrößtes Gewächshaus, versteckt auf Ebene 4 eines Kulturzentrums.', '["architecture","nature","free","hidden-gem"]', 'City of London', 'Barbican', 'free', 'Free, but ticketed', 'Kostenlos, aber Ticket nötig', '["sun"]', 1, '["Listed on the Open House programme for Sun 13 Sept","No large bags, luggage, prams or buggies"]', 'https://www.barbican.org.uk/whats-on/2026/event/visit-the-conservatory', 'Barbican Centre', 51.5202, -0.095, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('buckingham-palace-state-rooms', 1, 'builtin', 30, 'exceptional', 'Buckingham Palace State Rooms', 'Buckingham Palace – die Staatsgemächer', 'Nineteen state rooms, open 9 July to 27 September — so your dates just make it.', 'Neunzehn Staatsgemächer, Thronsaal, Gemäldegalerie. Geöffnet nur bis 27. September. Der Weiße Salon ist dieses Jahr wegen Restaurierung geschlossen.', '["royal","history","architecture"]', 'St James''s', 'Green Park / Victoria', 'paid', '£33 advance / £37 on the door', '33 £ vorab / 37 £ vor Ort', '["fri","sat","sun","mon","tue","wed"]', 1, '["White Drawing Room closed for restoration in 2026","Ballroom and parts of the Bow Room obscured by hoardings"]', 'https://www.rct.uk/visit/buckingham-palace', 'Buckingham Palace', 51.5008, -0.1419, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('changing-of-the-guard', 1, 'builtin', 31, 'popular', 'Changing of the Guard', 'Wachablösung am Buckingham Palace', 'Free, 45 minutes, bearskins and a military band. Usually Mon, Wed, Fri and Sun at 11:00 in September — confirm the date, it''s only published a month ahead. Stand at the Victoria Memorial and arrive early.', 'Kostenlos, 45 Minuten, Bärenfellmützen und Militärkapelle. Im September meist Mo, Mi, Fr und So um 11 Uhr – Termin vorher prüfen, er wird erst einen Monat vorher veröffentlicht. Am Victoria Memorial stehen und früh da sein.', '["icon","free","royal"]', 'St James''s', 'Green Park / St James''s Park', 'free', 'Free', 'Kostenlos', '["fri","sun","mon","wed"]', 0, '["Dates confirmed only ~a month ahead; cancelled in bad weather"]', 'https://www.householddivision.org.uk/changing-the-guard-calendar', 'Changing of the guard', 51.5008, -0.143, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('platform-9-3-4', 1, 'builtin', 32, 'popular', 'Platform 9¾, King''s Cross', 'Gleis 9¾, King''s Cross', 'The half-trolley through the wall, with a free photo if you bring your own camera — scarves and wands are handed out as props either way. Ten minutes'' queue at 08:00, up to two hours by lunchtime.', 'Der halb verschwundene Gepäckwagen in der Wand – das Foto mit eigener Kamera ist kostenlos, Schals und Zauberstäbe werden ohnehin als Requisiten gestellt. Um 8 Uhr zehn Minuten Schlange, mittags bis zu zwei Stunden.', '["harry-potter","free","icon"]', 'King''s Cross', 'King''s Cross St Pancras', 'free', 'Free (official print ~£9.50–25)', 'Kostenlos (offizieller Abzug ca. 9,50–25 £)', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://harrypottershop.co.uk/pages/kings-cross', 'Platform 9¾', 51.5324, -0.123, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('house-of-minalima', 1, 'builtin', 33, 'popular', 'House of MinaLima', 'House of MinaLima', 'Free, and better than it sounds: two floors of the actual graphic design from the films — the Marauder''s Map, the Daily Prophet, the Hogwarts letters — by the designers who made them.', 'Kostenlos und besser als es klingt: zwei Etagen mit dem echten Grafikdesign aus den Filmen – die Karte des Rumtreibers, der Tagesprophet, die Hogwarts-Briefe – von den Gestaltern selbst.', '["harry-potter","free","design"]', 'Soho', 'Oxford Circus / Piccadilly Circus', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://minalima.com/visit-us/', 'MinaLima', 51.5133, -0.1304, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('millennium-bridge', 1, 'builtin', 34, 'popular', 'Millennium Bridge', 'Millennium Bridge', 'The steel footbridge the Death Eaters twist apart in Half-Blood Prince, and the best straight-on approach to St Paul''s there is. Free, thirty seconds'' walk, and on the route you''re already taking.', 'Die Stahlbrücke, die die Todesser im Halbblutprinzen zerreißen – und der schönste Frontalzugang zu St Paul''s überhaupt. Kostenlos, dreißig Sekunden Fußweg und ohnehin auf Ihrer Route.', '["harry-potter","free","architecture"]', 'Bankside', 'St Paul''s / Blackfriars', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.cityoflondon.gov.uk/things-to-do/visit-the-city/attractions/millennium-bridge', 'Millennium Bridge, London', 51.5102, -0.0984, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('st-pancras-international', 1, 'builtin', 35, 'popular', 'St Pancras International', 'St Pancras International', 'Scott''s Gothic Revival hotel front, all red brick and spires, standing in for King''s Cross in the films — it''s where the flying Ford Anglia takes off. Free to walk into, and the Barlow trainshed behind it is a marvel.', 'Scotts neugotische Hotelfassade aus rotem Backstein und Türmchen, die in den Filmen King''s Cross darstellt – hier hebt der fliegende Ford Anglia ab. Frei zugänglich, und die Barlow-Bahnhofshalle dahinter ist ein Wunderwerk.', '["harry-potter","free","architecture"]', 'King''s Cross', 'King''s Cross St Pancras', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://stpancras.com/', 'St Pancras railway station', 51.53, -0.1253, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('rangers-house-bridgerton', 1, 'builtin', 36, 'popular', 'Ranger''s House — the Bridgerton house', 'Ranger''s House – das Bridgerton-Haus', 'The Bridgerton family home, wisteria and all, plus the Wernher Collection inside. Weekends only, 11:00–16:00, and it closes for the season on 21 September — so Sat 12 or Sun 13 is the only window.', 'Das Haus der Familie Bridgerton, samt Blauregen, dazu drinnen die Wernher-Sammlung. Nur am Wochenende, 11–16 Uhr, und ab 21. September Winterpause – Sa 12. oder So 13. ist das einzige Zeitfenster.', '["film","bridgerton","history"]', 'Blackheath / Greenwich', 'Greenwich / Blackheath', 'paid', '£10 · child £5.90', '10 £ · Kind 5,90 £', '["sat","sun"]', 1, '["Weekends only; closes for the season 21 Sept"]', 'https://www.english-heritage.org.uk/visit/places/rangers-house-the-wernher-collection/', 'Ranger''s House', 51.4734, -0.0016, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('royal-observatory-greenwich', 1, 'builtin', 37, 'popular', 'Royal Observatory, Greenwich', 'Royal Observatory Greenwich', 'Stand on the Prime Meridian, see Harrison''s sea clocks that solved longitude, and take the view back down over the Naval College to Canary Wharf — which is the real reason to climb the hill.', 'Auf dem Nullmeridian stehen, Harrisons Schiffsuhren sehen, die das Längengradproblem lösten – und den Blick über das Naval College bis Canary Wharf genießen, der eigentliche Grund für den Aufstieg.', '["history","views"]', 'Greenwich', 'Cutty Sark DLR', 'paid', '~£24 · Maritime Museum & Queen''s House free', 'ca. 24 £ · Maritime Museum & Queen''s House kostenlos', '["fri","sat","sun","mon","tue","wed"]', 1, '[]', 'https://www.rmg.co.uk/royal-observatory', 'Royal Observatory, Greenwich', 51.477, 0, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('shakespeares-globe', 1, 'builtin', 38, 'popular', 'Shakespeare''s Globe', 'Shakespeare''s Globe', 'A faithful reconstruction of the 1599 open-air playhouse, oak-framed and thatched, 200 metres from the original site. Tours daily; standing tickets in the yard are a few pounds if a play is on.', 'Eine originalgetreue Rekonstruktion des Freilufttheaters von 1599, aus Eichenholz und mit Reetdach, 200 Meter vom Originalstandort. Täglich Führungen; Stehplätze im Innenhof kosten bei Vorstellungen nur wenige Pfund.', '["history","theatre","icon"]', 'Bankside', 'London Bridge / Southwark', 'paid', 'Tour ticketed · standing tickets from ~£5', 'Führung kostenpflichtig · Stehplätze ab ca. 5 £', '["fri","sat","sun","mon","tue","wed"]', 1, '[]', 'https://www.shakespearesglobe.com/visit/', 'Shakespeare''s Globe', 51.5081, -0.0972, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('london-eye', 1, 'builtin', 39, 'popular', 'London Eye', 'London Eye', 'The postcard wheel. A 30-minute rotation with the best straight-on view of Parliament there is — and the honest catch: it''s the one high viewpoint that doesn''t contain the London Eye. Book a timed slot online; walk-up prices are worse and the queue is long.', 'Das Riesenrad von der Postkarte. Eine halbe Umdrehung in 30 Minuten, mit dem besten Frontalblick auf das Parlament überhaupt – und dem ehrlichen Haken, dass es der einzige Aussichtspunkt ist, auf dem man das London Eye nicht sieht. Zeitfenster online buchen; vor Ort ist es teurer und die Schlange lang.', '["views","icon"]', 'South Bank', 'Waterloo / Westminster', 'paid', 'from ~£30 online', 'ab ca. 30 £ online', '["fri","sat","sun","mon","tue","wed"]', 1, '["Cheaper and quicker with a timed online ticket","Horizon 22 and Sky Garden are free and higher"]', 'https://www.londoneye.com/', 'London Eye', 51.5033, -0.1194, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('view-from-the-shard', 1, 'builtin', 40, 'popular', 'The View from The Shard', 'The View from The Shard', 'Western Europe''s highest viewing gallery, floors 68–72, with an open-air deck at the top and no time limit once you''re up. Expensive — and Horizon 22 is free, though lower.', 'Die höchste Aussichtsgalerie Westeuropas, Stockwerke 68–72, oben mit Freiluftdeck und ohne Zeitlimit. Teuer – und Horizon 22 ist kostenlos, wenn auch niedriger.', '["views","icon"]', 'London Bridge', 'London Bridge', 'paid', 'from ~£32', 'ab ca. 32 £', '["fri","sat","sun","mon","tue","wed"]', 1, '["Horizon 22 is free, higher-value, and includes the Shard in the view"]', 'https://www.theviewfromtheshard.com/', 'The Shard', 51.5045, -0.0865, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('trafalgar-square', 1, 'builtin', 41, 'popular', 'Trafalgar Square', 'Trafalgar Square', 'Nelson''s Column, the lions, the Fourth Plinth''s rotating contemporary commission, and the National Gallery behind. Free, always open, and the centre of the city by definition — road distances to London are measured from here.', 'Nelsons Säule, die Löwen, der wechselnde zeitgenössische Auftrag auf dem Fourth Plinth und dahinter die National Gallery. Kostenlos, immer offen – und per Definition das Zentrum: alle Entfernungen nach London werden von hier gemessen.', '["icon","free"]', 'Westminster', 'Charing Cross', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.london.gov.uk/about-us/our-building-and-squares/trafalgar-square', 'Trafalgar Square', 51.5081, -0.1281, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('covent-garden-piazza', 1, 'builtin', 42, 'popular', 'Covent Garden Piazza', 'Covent Garden Piazza', 'The 1830 market hall, the Apple Market''s craft stalls, and street performers under the portico of St Paul''s Church — where the first recorded Punch and Judy show was staged in 1662.', 'Die Markthalle von 1830, die Kunsthandwerksstände des Apple Market und Straßenkünstler unter dem Portikus der St Paul''s Church – wo 1662 die erste dokumentierte Punch-and-Judy-Vorstellung stattfand.', '["icon","free","shopping"]', 'Covent Garden', 'Covent Garden', 'free', 'Free to wander', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.coventgarden.london/', 'Covent Garden', 51.5125, -0.1225, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('neal-s-yard-seven-dials-and-cecil-court', 1, 'builtin', 43, 'exceptional', 'Neal''s Yard, Seven Dials and Cecil Court', 'Neal''s Yard, Seven Dials und Cecil Court', 'Three minutes apart, best done as one loop.', 'Drei Minuten voneinander entfernt: ein winziger bunter Innenhof, eine Sternkreuzung von 1690 und eine intakte viktorianische Buchhändlergasse.', '["walk","free","shopping","photography"]', 'Covent Garden', 'Covent Garden / Leicester Square', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.sevendials.co.uk/', 'Neal''s Yard', 51.5144, -0.1265, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('piccadilly-circus', 1, 'builtin', 44, 'popular', 'Piccadilly Circus', 'Piccadilly Circus', 'The lit billboards, the Shaftesbury Memorial fountain everyone calls Eros, and the junction Londoners use as shorthand for the middle of everything. Ten minutes, at night.', 'Die Leuchtreklamen, der Shaftesbury-Brunnen, den alle Eros nennen, und die Kreuzung, die für Londoner schlicht „die Mitte von allem“ bedeutet. Zehn Minuten, am besten nachts.', '["icon","free"]', 'Soho', 'Piccadilly Circus', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.visitlondon.com/things-to-do/place/389944-piccadilly-circus', 'Piccadilly Circus', 51.51, -0.1344, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('camden-market', 1, 'builtin', 45, 'popular', 'Camden Market', 'Camden Market', 'Canal-side stalls, the Stables Market''s vintage warren, and street food from about forty countries. Chaotic and touristy, and still worth a couple of hours.', 'Stände am Kanal, das Vintage-Labyrinth des Stables Market und Streetfood aus rund vierzig Ländern. Chaotisch und touristisch – und trotzdem zwei Stunden wert.', '["market","shopping","free"]', 'Camden', 'Camden Town / Chalk Farm', 'free', 'Free to enter', 'Eintritt frei', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://camdenmarket.com/visit-us', 'Camden Market', 51.5414, -0.1464, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('notting-hill-portobello', 1, 'builtin', 46, 'popular', 'Notting Hill & Portobello Road', 'Notting Hill & Portobello Road', 'Pastel terraces, the blue door from the film, the Notting Hill Bookshop, and the antiques arcades. Friday and Saturday are the market days — Saturday is the full operation, Sunday is dead.', 'Pastellfarbene Häuserzeilen, die blaue Tür aus dem Film, der Notting Hill Bookshop und die Antiquitätenarkaden. Markt ist Freitag und Samstag – samstags in vollem Umfang, sonntags tot.', '["market","film","free"]', 'Notting Hill', 'Ladbroke Grove / Notting Hill Gate', 'free', 'Free', 'Kostenlos', '["fri","sat"]', 0, '[]', 'https://visitportobello.com/where/', 'Portobello Road', 51.5162, -0.2052, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('abbey-road-crossing', 1, 'builtin', 47, 'popular', 'Abbey Road crossing', 'Zebrastreifen Abbey Road', 'The zebra crossing from the Beatles cover, still a working road with impatient drivers. The studio wall is covered in fan graffiti and repainted every few months. Five minutes, and pure silliness.', 'Der Zebrastreifen vom Beatles-Cover – nach wie vor eine befahrene Straße mit ungeduldigen Autofahrern. Die Studiomauer ist voller Fan-Graffiti und wird alle paar Monate übermalt. Fünf Minuten reiner Unsinn.', '["icon","music","free"]', 'St John''s Wood', 'St John''s Wood', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.abbeyroad.com/crossing', 'Abbey Road', 51.532, -0.1782, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('richmond-park-in-rut-season', 1, 'builtin', 48, 'exceptional', 'Richmond Park in rut season', 'Richmond Park zur Brunftzeit', 'Six hundred free-roaming deer, and September is the rut.', 'Sechshundert frei lebende Hirsche – und im September ist Brunft. Die Hirsche röhren und kämpfen. Mindestens 50 Meter Abstand halten.', '["nature","walk","free","seasonal"]', 'Richmond', 'Richmond', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '["Keep at least 50 metres from the deer — during the rut they are genuinely dangerous"]', 'https://www.royalparks.org.uk/visit/parks/richmond-park', 'Richmond Park', 51.4433, -0.275, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('regent-s-canal-little-venice-to-camden', 1, 'builtin', 49, 'exceptional', 'Regent''s Canal: Little Venice to Camden', 'Regent''s Canal: Little Venice nach Camden', 'Forty-five minutes of towpath from a basin of moored narrowboats into Camden Lock.', '45 Minuten Treidelpfad von einem Becken voller Hausboote bis zum Camden Lock, vorbei am Regent''s Park und der Vogelvoliere des Zoos.', '["walk","free","hidden-gem"]', 'Maida Vale → Camden', 'Warwick Avenue → Camden Town', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://canalrivertrust.org.uk/places-to-visit/london', 'Regent''s Canal', 51.523, -0.1833, 'setup', 'setup', 0);
