  VALUES ('museum-of-the-home', 1, 'builtin', 50, 'exceptional', 'Museum of the Home', 'Museum of the Home', 'Actual living rooms from 1600 to now, in 18th-century almshouses.', 'Echte Wohnzimmer von 1600 bis heute, in Armenhäusern des 18. Jahrhunderts – darunter ein viktorianischer Séance-Salon und ein Shoreditch-Loft von 1998.', '["history","free","hidden-gem","design"]', 'Hoxton', 'Hoxton (Overground)', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","tue","wed"]', 0, '[]', 'https://www.museumofthehome.org.uk/', 'Museum of the Home', 51.5317, -0.0762, 'setup', 'setup', 0);
