  VALUES ('postman-s-park', 1, 'builtin', 51, 'exceptional', 'Postman''s Park', 'Postman''s Park', 'A tiled wall recording ordinary Victorians who died saving strangers.', 'Ein Gartenwinkel hinter St Paul''s mit einer Kachelwand, die an einfache Viktorianer erinnert, die beim Retten Fremder starben. Jede Kachel ein Satz.', '["history","free","hidden-gem"]', 'City of London', 'St Paul''s', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.cityoflondon.gov.uk/things-to-do/green-spaces/city-gardens/find-a-garden/postmans-park', 'Postman''s Park', 51.5168, -0.0976, 'setup', 'setup', 0);
