  VALUES ('royal-courts-of-justice', 1, 'builtin', 52, 'exceptional', 'Royal Courts of Justice', 'Royal Courts of Justice', 'Walk into the Great Hall, then sit in on a live Court of Appeal case.', 'Viktorianische Neugotik am Strand – die Great Hall ist frei zugänglich, und man kann sich in die Zuschauergalerie einer laufenden Berufungsverhandlung setzen.', '["architecture","history","free","unusual"]', 'Strand / Holborn', 'Temple / Holborn', 'free', 'Free', 'Kostenlos', '["fri","mon","tue","wed"]', 0, '["Main entrance is not wheelchair accessible; alternatives exist"]', 'https://www.gov.uk/courts-tribunals/royal-courts-of-justice', 'Royal Courts of Justice', 51.5136, -0.1133, 'setup', 'setup', 0);
