  VALUES ('battersea-power-station', 1, 'builtin', 53, 'exceptional', 'Battersea Power Station', 'Battersea Power Station', 'Giles Gilbert Scott''s cathedral of electricity, now walkable end to end.', 'Giles Gilbert Scotts Kathedrale der Elektrizität, heute frei begehbar – Turbinenhalle A im Art déco, Halle B im Edelstahl der 1950er.', '["architecture","free","shopping","film"]', 'Nine Elms', 'Battersea Power Station (Northern line)', 'free', 'Free to walk', 'Kostenlos begehbar', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://batterseapowerstation.co.uk/', 'Battersea Power Station', 51.4817, -0.1447, 'setup', 'setup', 0);
