  VALUES ('hyde-park-kensington-gardens', 1, 'builtin', 54, 'popular', 'Hyde Park & Kensington Gardens', 'Hyde Park & Kensington Gardens', '350 acres in the middle of the city: the Serpentine, the Italian Gardens, the Albert Memorial, Speakers'' Corner and the Peter Pan statue. Free, and the quickest way to stop feeling like a tourist.', '140 Hektar mitten in der Stadt: die Serpentine, die Italian Gardens, das Albert Memorial, Speakers'' Corner und die Peter-Pan-Statue. Kostenlos – und der schnellste Weg, sich nicht mehr wie ein Tourist zu fühlen.', '["park","free"]', 'Kensington', 'Hyde Park Corner / Lancaster Gate', 'free', 'Free', 'Kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.royalparks.org.uk/visit/parks/hyde-park', 'Hyde Park, London', 51.5086, -0.1636, 'setup', 'setup', 0);
INSERT OR IGNORE INTO items (id, trip_id, source, rank, tier, name, name_de, summary, summary_de, categories, area, station, cost, price_label, price_label_de, open_on, booking_required, flags, url, wiki, lat, lon, added_by, added_by_key, created_at)
  VALUES ('liberty-and-the-arcades', 1, 'builtin', 55, 'popular', 'Liberty & the Piccadilly arcades', 'Liberty & die Piccadilly-Arkaden', 'Mock-Tudor built in 1924 from the timbers of two Royal Navy warships, wrapped around galleried atriums — then the Burlington Arcade, still patrolled by top-hatted Beadles who forbid running, singing and whistling.', 'Ein Tudor-Nachbau von 1924 aus dem Holz zweier ausgemusterter Kriegsschiffe, um galerieartige Lichthöfe herum gebaut – dazu die Burlington Arcade, in der Beadles mit Zylinder noch immer Laufen, Singen und Pfeifen untersagen.', '["shopping","architecture","free"]', 'Soho / Piccadilly', 'Oxford Circus / Green Park', 'free', 'Free to browse', 'Stöbern kostenlos', '["fri","sat","sun","mon","tue","wed"]', 0, '[]', 'https://www.libertylondon.com/', 'Liberty (department store)', 51.5139, -0.1402, 'setup', 'setup', 0);
